/** Run one encoding through the translator's rules. */
export function runOne(m: Machine, at: number): void {
  let hex = '';
  for (let i = 0; i < 8; i += 1) {
    hex += m.byte(at + i).toString(16).toUpperCase().padStart(2, '0');
  }
  for (let len = 8; len >= 2; len -= 1) {
    const f = TABLE[hex.slice(0, len * 2)];
    if (f) { f(m); return; }
  }
  throw new Error('no rule for encoding ' + hex);
}